  add("Tara", tara, 3, "Health and well-being");
  const yg2 = YONI[groom.nakshatra], yb2 = YONI[bride.nakshatra];
  const enemy = YONI_ENEMY.some(([a, b]) => a === yg2 && b === yb2 || a === yb2 && b === yg2);
  add("Yoni", yg2 === yb2 ? 4 : enemy ? 0 : 2, 4, "Physical and intimate compatibility");
  const lg2 = LORD[groom.rashi], lb2 = LORD[bride.rashi];
  let gm;
  if (lg2 === lb2) gm = 5;
  else {
    const pair = [attitude(lg2, lb2), attitude(lb2, lg2)].sort().join("");
    gm = { FF: 5, FN: 4, NN: 3, EF: 1, EN: 0.5, EE: 0 }[pair];
  }
